import kotlin.test.Test
import kotlin.test.assertTrue

/**
 * Attacks never score lower than before the branch (fix loop 5): every attack row of the round-5
 * review (scratchpad r5/f1.txt, f2.txt, f3.txt, t1.txt, and round 6's r6-work/extra.txt: hrefs with tabs and newlines in the scheme,
 * backslash and slash mixes, HTML character references, userinfo behind CJK punctuation, stand-in
 * dots in a text URL's host) scores at least what origin/main (699761a since fix loop 7) gave it with the same probe
 * (the .b files in loupe-android-evidence/parity-fix7/probes). The floors are origin/main's scores (fix loop 7: the new origin/main, 699761a, formula v1.3), and round 7's
 * HTML documents whose links Chrome's DOMParser has (r7-work cases, cases2, cases3, adv6).
 * Generated by loupe-android-evidence/parity-fix5/mklegit.py; HostReadingTest holds the earlier rounds'.
 */
class AttackRowsTest {
    private class Row(val kind: Char, val input: String, val ceiling: Map<String, Int>, val note: Boolean = false)

    private val sender = "\"News\" <news@list.example.org>"

    private fun scores(r: Row): Map<String, Pair<Int, String>> = when (r.kind) {
        'U' -> {
            val site = SiteCheck.checkUrl(r.input).verdict
            val pw = SiteCheck.check(PageFacts(r.input, passwordFields = 1, forms = listOf(PageForm(password = true)))).verdict
            mapOf(
                "SITE" to (site.score to site.level), "PW" to (pw.score to pw.level),
                "MAIL" to Phishing.assess(sender, "", links = listOf(r.input to "Click here")).let { it.score to it.level },
                "SELF" to Phishing.assess(sender, "", links = listOf(r.input to r.input)).let { it.score to it.level },
                "TEXT" to Phishing.assess(sender, "Read more: ${r.input}").let { it.score to it.level },
            )
        }
        'S' -> {
            val f = r.input.split("||")
            mapOf("FROM" to Phishing.assess(f[0], "Your weekly update.", replyTo = f.getOrElse(1) { "" }).let { it.score to it.level })
        }
        'A' -> mapOf("HTML" to Phishing.assess(sender, "", links = MailMessage.anchors(r.input)).let { it.score to it.level })
        'M' -> r.input.split("\t", limit = 2).let { (snd, t) -> mapOf("T" to Phishing.assess(snd, t).let { it.score to it.level }) }
        'X' -> r.input.split("\t", limit = 2).let { (snd, h) -> mapOf("T" to Phishing.assess(snd, "", links = MailMessage.anchors(h)).let { it.score to it.level }) }
        'H' -> r.input.split("\t", limit = 2).let { (snd, h) ->
            mapOf("HTML" to Phishing.assess(snd, HtmlText.toText(h), links = MailMessage.anchors(h)).let { it.score to it.level })
        }
        else -> mapOf("T" to Phishing.assess(sender, r.input).let { it.score to it.level })
    }

    @Test
    fun `round-5 attacks never score lower than before the branch`() {
        val under = mutableListOf<String>()
        for (r in ROWS) for ((k, got) in scores(r)) {
            val floor = r.ceiling[k] ?: 0
            if (got.first < floor) under += "${r.kind} ${r.input} $k: ${got.first} < $floor"
        }
        assertTrue(under.isEmpty(), under.joinToString("\n"))
    }

